import re
for name in ['nm27c512n.hex','winbond w27c512-45.hex']:
    mem={}
    for ln in open(name):
        ln=ln.strip()
        if not ln.startswith(':'): continue
        b=bytes.fromhex(ln[1:])
        n,addr,typ=b[0],(b[1]<<8)|b[2],b[3]
        if typ==0:
            for i,d in enumerate(b[4:4+n]): mem[addr+i]=d
    ks=sorted(mem)
    print(name,'bytes',len(mem),'range %04x..%04x'%(ks[0],ks[-1]))
    # coverage gaps
    gaps=[]; prev=ks[0]
    for k in ks[1:]:
        if k!=prev+1: gaps.append((prev+1,k-1))
        prev=k
    print('  gaps:',[('%04x-%04x'%g) for g in gaps][:20], 'count',len(gaps))
    # ascii strings
    s=''.join(chr(mem[k]) if 32<=mem[k]<127 else '.' for k in ks)
    for m in re.finditer(r'[ -~]{6,}',s):
        pass
    print('  first strings:', [m.group() for m in re.finditer(r'[ -~]{6,}',s)][:25])
