mem={}
for ln in open('nm27c512n.hex'):
    ln=ln.strip()
    if not ln.startswith(':'): continue
    b=bytes.fromhex(ln[1:]); n,addr,typ=b[0],(b[1]<<8)|b[2],b[3]
    if typ==0:
        for i,d in enumerate(b[4:4+n]): mem[addr+i]=d
