    body = literal[1:-1]
    if body.startswith("\\"):
        simple = {"n": 10, "t": 9, "r": 13, "0": 0, "\\": 92, "'": 39, '"': 34}
        if body[1] in simple:
            return simple[body[1]]
        if body[1] == "x":
            return int(body[2:], 16)
        return int(body[1:], 8)
