def _unwind_to(frames: List[_Frame], kinds, inclusive: bool) -> None:
    """Handle ``break``/``continue`` raised inside a loop body.

    ``break`` drops the loop frame so execution continues after the loop;
    ``continue`` keeps the frame and rewinds its cursor so :meth:`_loop_tail`
    re-tests the condition (and runs the ``for`` step) as usual.
    """
    for index in range(len(frames) - 1, -1, -1):
        if frames[index].kind in kinds:
            if inclusive:
                del frames[index:]
            else:
                frames[index].i = 0
            return
    # an unmatched break must not hang the machine
