import sys; sys.path.insert(0,'.')
# Simulate the algorithm in Python to check it is right
def shl1(b):           # b = [b0,b1,b2,b3] BCD little-endian
    out=list(b); carry=0
    for i in range(4):
        cur=out[i]
        nxt=(cur>>4)&0xF
        out[i]=((cur<<4)&0xF0)|carry
        carry=nxt
    return out
def to_int(b): return int(''.join('%02X'%x for x in reversed(b)))
def from_int(v):
    s='%08X'%v; bs=[int(s[i:i+2],16) for i in range(6,-1,-2)]; return bs
for digits in ([5],[5,0],[5,0,0],[5,0,0,1]):
    b=[0,0,0,0]
    for d in digits:
        b=shl1(b); b[0]=b[0]|d
    print(' digits',digits,'-> BCD',[ '%02X'%x for x in b],'value',to_int(b))
"","description":"Verify the BCD shift algorithm in isolation"}

