{"command":"cd 'C:\Проекты VS\C проги и пай клиенты\test1\test'
$doomed = @()
foreach ($d in @('.', 'tools')) {
  $doomed += Get-ChildItem -Path $d -Filter '_patch*.py' -File -ErrorAction SilentlyContinue
  $doomed += Get-ChildItem -Path $d -Filter '*_probe.c' -File -ErrorAction SilentlyContinue
}
$doomed += Get-ChildItem -Path . -Filter '_real_check.py' -File -ErrorAction SilentlyContinue
$doomed | ForEach-Object { 'rm ' + $_.FullName.Replace($PWD.Path+'\','') }
$doomed | Remove-Item -Force -ErrorAction SilentlyContinue
""
